import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { expectRecordTitle, recordIdFromView, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 Create Contact with valid data from Account - regression verification', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-044 Create Contact with valid data from Account - regression verification',
    { tag: ['@functional', '@P1', '@SF-219', '@persona:sales-rep', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P1',
        severity: 'major',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-044',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const email1 = data.unique('email-1');
      const phone1Phone = data.unique('phone-1', 'phone');
      const viewed: Record<string, string> = {};
      await data.create('account-contact', ['Account']);
      await test.step('1. Navigate to the Account record page and open the Contacts related list', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): Account record page displays with Contacts related list visible
        await accountRecordPage.open(data.id('Account'));
        viewed['account'] = await recordIdFromView(page, 'Account');
        await expectRecordTitle(page, data.value('Account', 'Name'));
      });
      await test.step('2. Click New in the Contacts related list', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): New Contact modal opens with Account Name field pre-populated with the Account name
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await expect(newContactDialog.root).toBeVisible();
      });
      await test.step("3. Enter required fields: First Name 'Jane', Last Name 'Smith', Email '<EMAIL_1>', Phone '<PHONE_1>', Title 'Director'", async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): All required fields accept the entered values
        await newContactDialog.firstName.fill('Jane');
        await newContactDialog.lastName.fill('Smith');
        await newContactDialog.email.fill(email1);
        await newContactDialog.phone.fill(phone1Phone);
        await newContactDialog.title.fill('Director');
        await expect(newContactDialog.firstName).toHaveValue('Jane');
        await expect(newContactDialog.lastName).toHaveValue('Smith');
        await expect(newContactDialog.email).toHaveValue(email1);
        await expect(newContactDialog.phone).toHaveValue(phone1Phone);
        await expect(newContactDialog.title).toHaveValue('Director');
      });
      await test.step('4. Click Save', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): Contact record is created and the Contact detail page opens
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        viewed['contact'] = await recordIdFromView(page, 'Contact');
        await data.adoptCreated('contact', 'Contact', viewed['contact']);
        await expectRecordTitle(page, 'Smith');
      });
      await test.step('5. Verify the Contact was created and linked to the Account', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): Contact detail page shows the correct Account Name and all entered field values are displayed
        await expect
          .poll(() => soqlValue(sf, 'Contact', viewed['contact'] ?? '', 'AccountId'))
          .toBe(data.id('Account'));
        await expect.poll(() => soqlValue(sf, 'Contact', viewed['contact'] ?? '', 'FirstName')).toBe('Jane');
        await expect.poll(() => soqlValue(sf, 'Contact', viewed['contact'] ?? '', 'LastName')).toBe('Smith');
        await expect.poll(() => soqlValue(sf, 'Contact', viewed['contact'] ?? '', 'Email')).toBe(email1);
        await expect.poll(() => soqlValue(sf, 'Contact', viewed['contact'] ?? '', 'Phone')).toBe(phone1Phone);
        await expect.poll(() => soqlValue(sf, 'Contact', viewed['contact'] ?? '', 'Title')).toBe('Director');
      });
    },
  );
});
